-- ==============================================================================
-- COLORLINK · Catálogo detallado
-- 1. Agrega la ficha técnica a cada producto (beneficios, usos y especificaciones).
-- 2. Actualiza nombres, descripciones, presentaciones y precios del catálogo inicial.
-- 3. Agrega productos de uso frecuente (esmaltes, anticorrosivo, pisos, lijas, cinta).
-- No modifica el stock ni el costo de los productos que ya existen.
-- Precios en COP con IVA incluido (referencia de mercado, ajústalos en el panel).
-- ==============================================================================

alter table public.productos add column if not exists ficha jsonb not null default '{}'::jsonb;

insert into public.productos
  (sku, slug, nombre, descripcion, categoria, presentacion, unidad, precio, precio_anterior, costo, stock, stock_minimo,
   color_hex, acabado, rendimiento_m2, destacado, ficha)
values
